/**
 * Unit tests for CpioArchiveOutputStream.close()
 */
public class CpioArchiveOutputStream_close_TriageGen0Test {





    /**
     * Tests that an IOException from the underlying stream is propagated.
     * This ensures the super.close() call is actually executed and its exceptions handled.
     */
    @Test(expected = IOException.class)
    public void testClose_WhenSuperCloseThrowsException_PropagatesException() throws IOException {
        OutputStream errorStream = new IOExceptionOutputStream();
        CpioArchiveOutputStream cos = new CpioArchiveOutputStream(errorStream);

        cos.close();
    }

    /**
     * Mock OutputStream that always throws an IOException on close.
     */
    private static class IOExceptionOutputStream extends OutputStream {
        @Override
